#!/usr/bin/env node

/**
 * NOTE! This is entirely autogenerated code. I barely reviewed this portion, so
 * take if for a grain of salt. I wouldn't have so many freaking emojis.
 *
 * ------------------------------------------------------------------------------
 *
 * Generate Unfurl Assets for Social Media Previews
 *
 * Takes high-resolution inputs (2400x1260) and generates all unfurl formats (1200x630).
 *
 * Prerequisites:
 *   - ffmpeg (brew install ffmpeg)
 *
 * Input files (you control these):
 *   - public/unfurls/main_input.mov  - Source video (2400x1260, 3-5 second loop)
 *   - public/unfurls/main_input.png  - Source static image (2400x1260)
 *
 * Output files (generated):
 *   - public/unfurls/main.mp4        - Optimized video for iMessage
 *   - public/unfurls/main.gif        - Animated GIF for Discord/Slack/LinkedIn
 *   - public/unfurls/main-static.png - Static image (1200x630)
 *   - public/unfurls/main-static.jpg - JPG variant
 *   - public/unfurls/main-static.webp - WebP variant
 *
 * Usage:
 *   node scripts/generate-unfurl-assets.js
 *   # or via Makefile:
 *   make unfurl-assets
 */

import { execSync } from "child_process";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Configuration
const UNFURLS_DIR = path.join(__dirname, "../public/unfurls");

// Input files (high resolution sources)
const INPUTS = {
  mov: path.join(UNFURLS_DIR, "main_input.mov"),
  png: path.join(UNFURLS_DIR, "main_input.png"), // 2400x1260 (2x resolution)
};

// Output files (1200x630 for unfurls)
const OUTPUTS = {
  mp4: path.join(UNFURLS_DIR, "main.mp4"),
  gif: path.join(UNFURLS_DIR, "main.gif"),
  png: path.join(UNFURLS_DIR, "main-static.png"),
  jpg: path.join(UNFURLS_DIR, "main-static.jpg"),
  webp: path.join(UNFURLS_DIR, "main-static.webp"),
};

function run(cmd, description) {
  console.log(`\n📦 ${description}...`);
  console.log(`   $ ${cmd}`);
  try {
    execSync(cmd, { stdio: "inherit" });
    console.log(`   ✅ Done`);
    return true;
  } catch (error) {
    console.error(`   ❌ Failed: ${error.message}`);
    return false;
  }
}

function checkPrerequisites() {
  console.log("🔍 Checking prerequisites...\n");

  // Check for ffmpeg
  try {
    execSync("which ffmpeg", { stdio: "pipe" });
    console.log("   ✅ ffmpeg found");
  } catch {
    console.error("   ❌ ffmpeg not found. Install with: brew install ffmpeg");
    process.exit(1);
  }

  // Check for source video
  if (!fs.existsSync(INPUTS.mov)) {
    console.error(`\n❌ Source video not found: ${INPUTS.mov}`);
    console.error(`
To create the unfurl video:
  1. Run: make dev-website
  2. Navigate to: http://localhost:3000/unfurl
  3. Use Kap (https://getkap.co/) or QuickTime to record
  4. Record a 3-5 second loop at 2400x1260 (2x resolution)
  5. Save to: ${INPUTS.mov}
  6. Re-run this script
`);
    process.exit(1);
  }

  const videoStats = fs.statSync(INPUTS.mov);
  const videoSizeMB = (videoStats.size / (1024 * 1024)).toFixed(2);
  console.log(`   ✅ Source video found: main_input.mov (${videoSizeMB} MB)`);

  // Check for source PNG
  if (!fs.existsSync(INPUTS.png)) {
    console.error(`\n❌ Source PNG not found: ${INPUTS.png}`);
    console.error(`
To create the static image:
  1. Take a screenshot from the unfurl page at 2400x1260
  2. Save to: ${INPUTS.png}
  3. Re-run this script
`);
    process.exit(1);
  }

  const pngStats = fs.statSync(INPUTS.png);
  const pngSizeMB = (pngStats.size / (1024 * 1024)).toFixed(2);
  console.log(`   ✅ Source PNG found: main_input.png (${pngSizeMB} MB)`);
}

function ensureDir() {
  if (!fs.existsSync(UNFURLS_DIR)) {
    fs.mkdirSync(UNFURLS_DIR, { recursive: true });
    console.log(`📁 Created directory: ${UNFURLS_DIR}`);
  }
}

async function generateAssets() {
  console.log("\n🎬 Generating unfurl assets from inputs...\n");

  // 1. Generate optimized MP4 (for iMessage and general use)
  // Using h.264 codec, yuv420p for compatibility, faststart for web streaming
  // Scales from 2400x1260 to 1200x630
  run(
    `ffmpeg -y -i "${INPUTS.mov}" -c:v libx264 -preset medium -crf 23 -pix_fmt yuv420p -movflags +faststart -vf "scale=1200:630:flags=lanczos" -an "${OUTPUTS.mp4}"`,
    "Converting MOV to optimized MP4 (1200x630)"
  );

  // 2. Generate GIF (for Discord, Slack, LinkedIn)
  // Two-pass for better quality: first generate palette, then use it
  // Scales from 2400x1260 to 1200x630
  const palettePath = path.join(UNFURLS_DIR, "palette.png");
  run(
    `ffmpeg -y -i "${INPUTS.mov}" -vf "fps=15,scale=1200:630:flags=lanczos,palettegen=stats_mode=diff" "${palettePath}"`,
    "Generating color palette for GIF"
  );
  run(
    `ffmpeg -y -i "${INPUTS.mov}" -i "${palettePath}" -lavfi "fps=15,scale=1200:630:flags=lanczos[x];[x][1:v]paletteuse=dither=bayer:bayer_scale=5:diff_mode=rectangle" "${OUTPUTS.gif}"`,
    "Converting to high-quality GIF (1200x630)"
  );
  // Clean up palette
  if (fs.existsSync(palettePath)) {
    fs.unlinkSync(palettePath);
  }

  // 3. Scale input PNG to output PNG (2400x1260 -> 1200x630)
  run(
    `ffmpeg -y -i "${INPUTS.png}" -vf "scale=1200:630:flags=lanczos" "${OUTPUTS.png}"`,
    "Scaling PNG to 1200x630"
  );

  // 4. Convert PNG to JPG (smaller file, good compatibility)
  run(
    `ffmpeg -y -i "${OUTPUTS.png}" -q:v 2 "${OUTPUTS.jpg}"`,
    "Converting PNG to JPG"
  );

  // 5. Convert PNG to WebP (best compression for modern browsers)
  run(
    `ffmpeg -y -i "${OUTPUTS.png}" -quality 90 "${OUTPUTS.webp}"`,
    "Converting PNG to WebP"
  );

  // Print summary
  console.log("\n" + "=".repeat(50));
  console.log("✨ All assets generated!\n");

  const files = fs.readdirSync(UNFURLS_DIR).filter((f) => !f.startsWith("."));
  const inputFiles = files.filter((f) => f.startsWith("main_input"));
  const outputFiles = files.filter((f) => !f.startsWith("main_input"));

  console.log("📥 Inputs (2400x1260):");
  inputFiles.sort().forEach((file) => {
    const filePath = path.join(UNFURLS_DIR, file);
    const stats = fs.statSync(filePath);
    const sizeMB = (stats.size / (1024 * 1024)).toFixed(2);
    console.log(`   ${file.padEnd(25)} ${sizeMB} MB`);
  });

  console.log("\n📤 Outputs (1200x630):");
  outputFiles.sort().forEach((file) => {
    const filePath = path.join(UNFURLS_DIR, file);
    const stats = fs.statSync(filePath);
    const sizeKB = (stats.size / 1024).toFixed(1);
    const sizeMB = (stats.size / (1024 * 1024)).toFixed(2);
    const sizeStr = stats.size > 1024 * 1024 ? `${sizeMB} MB` : `${sizeKB} KB`;
    console.log(`   ${file.padEnd(25)} ${sizeStr}`);
  });

  console.log(`
📋 Next steps:
  1. Test your unfurls:
     - Discord: Paste URL in a test server
     - LinkedIn: https://www.linkedin.com/post-inspector/
     - Twitter: https://cards-dev.twitter.com/validator
     - Facebook: https://developers.facebook.com/tools/debug/

  2. Deploy and test on actual platforms

  3. Note: Platforms cache aggressively - add ?v=2 to URLs to bust cache
`);
}

// Main
async function main() {
  console.log("🎨 Unfurl Asset Generator\n");
  console.log("=".repeat(50));
  console.log("Inputs:");
  console.log(`  Video: main_input.mov (2400x1260)`);
  console.log(`  PNG:   main_input.png (2400x1260)`);
  console.log("Outputs: (1200x630)");
  console.log(`  main.mp4, main.gif, main-static.{png,jpg,webp}`);
  console.log("=".repeat(50));

  ensureDir();
  checkPrerequisites();
  await generateAssets();
}

main().catch(console.error);
